{
  "name": "Beauty Blender Pro",
  "description": "The ultimate smart companion for makeup sponge enthusiasts. Features include personalized recommendations, technique tutorials, automated cleaning reminders, and AI-powered makeup diagnosis.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface SpongeRecommendation {
  shape: string;
  material: string;
  reason: string;
  imageUrl: string;
}

export enum SkinType {
  DRY = 'Dry',
  OILY = 'Oily',
  COMBINATION = 'Combination',
  NORMAL = 'Normal'
}

export enum FinishType {
  DEWY = 'Dewy',
  MATTE = 'Matte',
  SATIN = 'Natural Satin'
}

export interface QuizState {
  skinType: SkinType | null;
  finish: FinishType | null;
  formula: string | null;
  concern: string | null;
}

export interface SubscriptionStatus {
  active: boolean;
  startDate?: string;
  nextShipmentDate?: string;
  plan: string;
}

export interface DiagnosticReport {
  overallScore: number;
  dimensions: {
    blendability: number;
    evenness: number;
    naturalism: number;
    detailWork: number;
  };
  advice: string;
}

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { DiagnosticReport } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeMakeupResult = async (base64Image: string): Promise<DiagnosticReport> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: "Analyze this makeup application photo. Evaluate blendability, evenness, naturalism, and detail work. Provide a score out of 100 and specific actionable advice using a makeup sponge." },
            {
              inlineData: {
                mimeType: 'image/jpeg',
                data: base64Image
              }
            }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            overallScore: { type: Type.NUMBER },
            dimensions: {
              type: Type.OBJECT,
              properties: {
                blendability: { type: Type.NUMBER },
                evenness: { type: Type.NUMBER },
                naturalism: { type: Type.NUMBER },
                detailWork: { type: Type.NUMBER }
              },
              required: ["blendability", "evenness", "naturalism", "detailWork"]
            },
            advice: { type: Type.STRING }
          },
          required: ["overallScore", "dimensions", "advice"]
        }
      }
    });

    return JSON.parse(response.text || '{}') as DiagnosticReport;
  } catch (error) {
    console.error("Diagnosis error:", error);
    throw error;
  }
};

export const editMakeupImage = async (base64Image: string, prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/png' } },
          { text: prompt }
        ]
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image generated");
  } catch (error) {
    console.error("Image editing error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Play, Pause, RotateCcw } from 'lucide-react';

interface RhythmTimerProps {
  onComplete?: () => void;
}

const RhythmTimer: React.FC<RhythmTimerProps> = ({ onComplete }) => {
  const [timeLeft, setTimeLeft] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [isActive, setIsActive] = useState(false);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  const startTimer = (seconds: number) => {
    setTotalTime(seconds);
    setTimeLeft(seconds);
    setIsActive(true);
  };

  const toggleActive = () => setIsActive(!isActive);

  const reset = () => {
    setIsActive(false);
    setTimeLeft(0);
    setTotalTime(0);
  };

  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      if (isActive && onComplete) onComplete();
      setIsActive(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft, onComplete]);

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const percentage = totalTime > 0 ? (timeLeft / totalTime) * 100 : 0;

  return (
    <div className="bg-white rounded-3xl p-6 shadow-xl border border-pink-100 flex flex-col items-center">
      <div className="relative w-48 h-48 mb-6">
        <svg className="w-full h-full -rotate-90">
          <circle
            cx="96"
            cy="96"
            r="88"
            fill="none"
            stroke="#fce7f3"
            strokeWidth="12"
          />
          <circle
            cx="96"
            cy="96"
            r="88"
            fill="none"
            stroke="#ec4899"
            strokeWidth="12"
            strokeDasharray={552.92}
            strokeDashoffset={552.92 - (552.92 * percentage) / 100}
            strokeLinecap="round"
            className="transition-all duration-1000 ease-linear"
          />
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className="text-4xl font-bold text-pink-600">{formatTime(timeLeft)}</span>
          <span className="text-xs uppercase tracking-widest text-pink-400 font-medium">Remaining</span>
        </div>
      </div>

      <div className="flex gap-4 mb-6">
        {[180, 300, 600].map((s) => (
          <button
            key={s}
            onClick={() => startTimer(s)}
            className="px-4 py-2 rounded-full bg-pink-100 text-pink-600 font-semibold hover:bg-pink-200 transition-colors"
          >
            {s / 60} MIN
          </button>
        ))}
      </div>

      <div className="flex gap-4">
        <button
          onClick={toggleActive}
          disabled={timeLeft === 0}
          className={`w-12 h-12 flex items-center justify-center rounded-full ${isActive ? 'bg-gray-200 text-gray-600' : 'bg-pink-500 text-white'} transition-colors disabled:opacity-50`}
        >
          {isActive ? <Pause size={24} /> : <Play size={24} />}
        </button>
        <button
          onClick={reset}
          className="w-12 h-12 flex items-center justify-center rounded-full bg-gray-100 text-gray-600 hover:bg-gray-200 transition-colors"
        >
          <RotateCcw size={24} />
        </button>
      </div>
    </div>
  );
};

export default RhythmTimer;

import React, { useState } from 'react';
import { SkinType, FinishType, QuizState, SpongeRecommendation } from '../types';
import { ChevronRight, RefreshCw, Star } from 'lucide-react';

const Quiz: React.FC = () => {
  const [step, setStep] = useState(0);
  const [quiz, setQuiz] = useState<QuizState>({
    skinType: null,
    finish: null,
    formula: null,
    concern: null,
  });
  const [result, setResult] = useState<SpongeRecommendation | null>(null);

  const steps = [
    {
      title: "What's your skin type?",
      key: 'skinType',
      options: Object.values(SkinType),
    },
    {
      title: "Desired finish?",
      key: 'finish',
      options: Object.values(FinishType),
    },
    {
      title: "Favorite foundation formula?",
      key: 'formula',
      options: ['Liquid', 'Cream', 'Stick', 'Cushion'],
    },
    {
      title: "Main concern?",
      key: 'concern',
      options: ['Coverage', 'Longevity', 'Blendability'],
    }
  ];

  const handleSelect = (val: any) => {
    const updated = { ...quiz, [steps[step].key]: val };
    setQuiz(updated);
    if (step < steps.length - 1) {
      setStep(step + 1);
    } else {
      generateResult(updated);
    }
  };

  const generateResult = (data: QuizState) => {
    // Mock algorithm logic
    const rec: SpongeRecommendation = {
      shape: data.finish === FinishType.MATTE ? 'Angled Flat Edge' : 'Classic Teardrop',
      material: data.skinType === SkinType.DRY ? 'Hydrophilic Velvet' : 'Latex-Free PU',
      reason: `Based on your ${data.skinType} skin and preference for a ${data.finish} finish, this ${data.formula}-optimized sponge will solve your ${data.concern} issues.`,
      imageUrl: 'https://picsum.photos/seed/sponge/400/400'
    };
    setResult(rec);
  };

  if (result) {
    return (
      <div className="bg-white rounded-3xl p-8 shadow-2xl animate-fade-in text-center">
        <div className="inline-block p-2 bg-pink-100 text-pink-600 rounded-full mb-4">
          <Star className="w-6 h-6 fill-current" />
        </div>
        <h2 className="text-3xl font-bold text-gray-800 mb-2">Your Perfect Match!</h2>
        <p className="text-gray-500 mb-8">The "Precision Pro" Blender</p>

        <div className="relative w-64 h-64 mx-auto mb-8 rounded-full bg-gradient-to-tr from-pink-200 to-rose-100 flex items-center justify-center p-4">
          <img src={result.imageUrl} alt="Recommended Sponge" className="rounded-2xl shadow-lg transform rotate-12 hover:rotate-0 transition-transform duration-500" />
        </div>

        <div className="space-y-4 text-left bg-pink-50 p-6 rounded-2xl mb-8">
          <div>
            <h4 className="font-bold text-pink-600 uppercase text-xs tracking-wider">Optimal Shape</h4>
            <p className="text-gray-800">{result.shape}</p>
          </div>
          <div>
            <h4 className="font-bold text-pink-600 uppercase text-xs tracking-wider">Ideal Material</h4>
            <p className="text-gray-800">{result.material}</p>
          </div>
          <p className="text-sm text-gray-600 leading-relaxed italic border-l-4 border-pink-300 pl-4">
            "{result.reason}"
          </p>
        </div>

        <button 
          onClick={() => { setStep(0); setResult(null); }}
          className="flex items-center justify-center gap-2 w-full py-4 bg-pink-600 text-white rounded-2xl font-bold shadow-lg hover:bg-pink-700 transition-all"
        >
          <RefreshCw size={20} /> Retake Quiz
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto">
      <div className="flex justify-between items-center mb-8">
        <h2 className="text-2xl font-bold">Step {step + 1} of {steps.length}</h2>
        <div className="w-32 h-2 bg-gray-200 rounded-full">
          <div 
            className="h-full bg-pink-500 rounded-full transition-all duration-500" 
            style={{ width: `${((step + 1) / steps.length) * 100}%` }}
          />
        </div>
      </div>

      <div className="bg-white rounded-3xl p-8 shadow-xl">
        <h3 className="text-xl font-bold text-gray-800 mb-6">{steps[step].title}</h3>
        <div className="space-y-4">
          {steps[step].options.map((opt) => (
            <button
              key={opt}
              onClick={() => handleSelect(opt)}
              className="w-full flex justify-between items-center p-4 rounded-2xl border-2 border-gray-100 hover:border-pink-300 hover:bg-pink-50 transition-all text-left"
            >
              <span className="font-medium text-gray-700">{opt}</span>
              <ChevronRight className="text-pink-400" />
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Quiz;

import React, { useState } from 'react';
import { analyzeMakeupResult } from '../services/geminiService';
import { DiagnosticReport } from '../types';
import { Upload, Loader2, CheckCircle2, AlertCircle } from 'lucide-react';

const AIDiagnosis: React.FC = () => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [report, setReport] = useState<DiagnosticReport | null>(null);

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image) return;
    setLoading(true);
    try {
      const base64 = image.split(',')[1];
      const result = await analyzeMakeupResult(base64);
      setReport(result);
    } catch (err) {
      alert("Failed to analyze. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8">
      <div className="bg-white rounded-3xl p-8 shadow-xl text-center">
        <h2 className="text-3xl font-bold mb-2">Today's Look AI Diagnosis</h2>
        <p className="text-gray-500 mb-8">Upload a selfie to get professional feedback on your blend technique.</p>

        {!image ? (
          <label className="flex flex-col items-center justify-center w-full h-64 border-2 border-dashed border-pink-200 rounded-3xl cursor-pointer hover:bg-pink-50 transition-colors">
            <Upload className="w-12 h-12 text-pink-400 mb-4" />
            <span className="text-gray-600 font-medium">Click to upload photo</span>
            <input type="file" className="hidden" accept="image/*" onChange={handleUpload} />
          </label>
        ) : (
          <div className="space-y-6">
            <img src={image} alt="Selfie" className="w-full h-80 object-cover rounded-2xl shadow-md" />
            {!report && (
              <button
                onClick={handleAnalyze}
                disabled={loading}
                className="w-full py-4 bg-pink-600 text-white rounded-2xl font-bold shadow-lg hover:bg-pink-700 disabled:opacity-50 flex items-center justify-center gap-2"
              >
                {loading ? <Loader2 className="animate-spin" /> : "Analyze My Look"}
              </button>
            )}
            <button 
              onClick={() => { setImage(null); setReport(null); }}
              className="text-pink-600 font-semibold"
            >
              Upload Different Photo
            </button>
          </div>
        )}
      </div>

      {report && (
        <div className="bg-white rounded-3xl p-8 shadow-xl animate-slide-up">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h3 className="text-2xl font-bold">Diagnostic Report</h3>
              <p className="text-gray-500">Based on AI image recognition</p>
            </div>
            <div className="text-right">
              <span className="text-5xl font-bold text-pink-600">{report.overallScore}</span>
              <span className="text-pink-300 font-bold">/100</span>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 mb-8">
            {Object.entries(report.dimensions).map(([key, val]) => (
              <div key={key} className="p-4 bg-pink-50 rounded-2xl border border-pink-100">
                <div className="flex justify-between items-center mb-2">
                  <span className="text-xs uppercase font-bold text-pink-600 tracking-wider">
                    {key.replace(/([A-Z])/g, ' $1')}
                  </span>
                  {val >= 80 ? <CheckCircle2 size={16} className="text-green-500" /> : <AlertCircle size={16} className="text-amber-500" />}
                </div>
                <div className="w-full h-1.5 bg-pink-200 rounded-full">
                  <div 
                    className="h-full bg-pink-500 rounded-full" 
                    style={{ width: `${val}%` }}
                  />
                </div>
              </div>
            ))}
          </div>

          <div className="bg-gray-50 p-6 rounded-2xl border-l-4 border-pink-500">
            <h4 className="font-bold text-gray-800 mb-2">Expert Advice</h4>
            <p className="text-gray-600 leading-relaxed">{report.advice}</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default AIDiagnosis;

import React, { useState, useEffect } from 'react';
import { Droplets, Wind, Sparkles, CheckCircle } from 'lucide-react';
import RhythmTimer from './RhythmTimer';

const CareAssistant: React.FC = () => {
  const [uses, setUses] = useState(3);
  const [showDryTimer, setShowDryTimer] = useState(false);

  const logUse = () => setUses((prev) => (prev >= 7 ? 0 : prev + 1));

  const washStatus = uses >= 5 ? 'DIRTY' : uses >= 3 ? 'FAIR' : 'CLEAN';

  return (
    <div className="grid md:grid-cols-2 gap-8">
      <div className="space-y-8">
        <div className="bg-white rounded-3xl p-8 shadow-xl">
          <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
            <Sparkles className="text-pink-500" /> Usage Tracker
          </h2>
          <div className="flex items-end justify-between mb-8">
            <div>
              <p className="text-4xl font-bold text-gray-800">{uses}</p>
              <p className="text-gray-500">Uses since last wash</p>
            </div>
            <div className={`px-4 py-1 rounded-full text-xs font-bold tracking-widest ${
              washStatus === 'CLEAN' ? 'bg-green-100 text-green-600' :
              washStatus === 'FAIR' ? 'bg-amber-100 text-amber-600' : 'bg-red-100 text-red-600'
            }`}>
              {washStatus}
            </div>
          </div>

          <div className="flex gap-2 mb-8">
            {[...Array(7)].map((_, i) => (
              <div 
                key={i} 
                className={`h-2 flex-1 rounded-full ${i < uses ? 'bg-pink-500' : 'bg-gray-200'}`} 
              />
            ))}
          </div>

          <button 
            onClick={logUse}
            className="w-full py-4 bg-pink-100 text-pink-600 rounded-2xl font-bold hover:bg-pink-200 transition-colors mb-4"
          >
            Log Today's Use
          </button>

          {uses >= 5 && (
            <div className="bg-rose-50 border border-rose-100 p-4 rounded-2xl flex items-center gap-3 animate-pulse">
              <Droplets className="text-rose-500 shrink-0" />
              <p className="text-sm text-rose-800 font-medium">Your sponge needs a bath! 🛁 Bacterial buildup is starting.</p>
            </div>
          )}
        </div>

        <div className="bg-gradient-to-br from-blue-500 to-indigo-600 rounded-3xl p-8 text-white shadow-xl">
          <h3 className="text-xl font-bold mb-4 flex items-center gap-2">
            <Wind /> Dry-Timer
          </h3>
          <p className="text-blue-100 mb-6 text-sm">Always ensure your sponge is bone-dry before storing to prevent mold.</p>
          {!showDryTimer ? (
            <button 
              onClick={() => setShowDryTimer(true)}
              className="w-full py-3 bg-white/20 hover:bg-white/30 rounded-xl font-bold transition-all"
            >
              Start Dry Count-down
            </button>
          ) : (
            <RhythmTimer onComplete={() => alert("Your sponge is fully dry and ready to use!")} />
          )}
        </div>
      </div>

      <div className="bg-white rounded-3xl p-8 shadow-xl">
        <h2 className="text-2xl font-bold mb-6">Cleaning Guide</h2>
        <div className="space-y-6">
          {[
            { step: 1, title: 'Wet', text: 'Saturate your sponge under lukewarm water.' },
            { step: 2, title: 'Lather', text: 'Apply mild cleanser or sponge soap.' },
            { step: 3, title: 'Rinse', text: 'Squeeze under running water until it runs clear.' },
            { step: 4, title: 'Squeeze', text: 'Press out excess water with a clean towel.' },
          ].map((s) => (
            <div key={s.step} className="flex gap-4">
              <div className="w-10 h-10 rounded-full bg-pink-100 text-pink-600 flex items-center justify-center font-bold shrink-0">
                {s.step}
              </div>
              <div>
                <h4 className="font-bold text-gray-800">{s.title}</h4>
                <p className="text-sm text-gray-500">{s.text}</p>
              </div>
            </div>
          ))}
          <div className="pt-6 border-t">
            <img src="https://picsum.photos/seed/cleaning/400/250" className="rounded-2xl w-full" alt="Cleaning tutorial" />
          </div>
        </div>
      </div>
    </div>
  );
};

export default CareAssistant;

import React, { useState } from 'react';
import { editMakeupImage } from '../services/geminiService';
import { Wand2, Loader2, Download, Trash2, Camera } from 'lucide-react';

const ImageEditor: React.FC = () => {
  const [source, setSource] = useState<string | null>(null);
  const [result, setResult] = useState<string | null>(null);
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = () => setSource(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleEdit = async () => {
    if (!source || !prompt) return;
    setLoading(true);
    try {
      const base64 = source.split(',')[1];
      const edited = await editMakeupImage(base64, prompt);
      setResult(edited);
    } catch (err) {
      alert("Failed to edit image.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      <div className="bg-white rounded-3xl p-8 shadow-xl mb-8">
        <h2 className="text-3xl font-bold mb-2 flex items-center gap-3">
          <Wand2 className="text-pink-500" /> AI Creative Lab
        </h2>
        <p className="text-gray-500 mb-8">Use text commands to edit your makeup photos instantly.</p>

        {!source ? (
          <label className="flex flex-col items-center justify-center w-full h-80 border-2 border-dashed border-gray-200 rounded-3xl cursor-pointer hover:bg-gray-50 transition-all">
            <Camera className="w-12 h-12 text-gray-300 mb-4" />
            <span className="text-gray-600">Drop a photo here or click to browse</span>
            <input type="file" className="hidden" onChange={handleFile} />
          </label>
        ) : (
          <div className="grid md:grid-cols-2 gap-8 mb-8">
            <div className="space-y-2">
              <span className="text-xs font-bold uppercase text-gray-400">Original</span>
              <img src={source} className="w-full h-64 object-cover rounded-2xl" alt="Original" />
            </div>
            <div className="space-y-2">
              <span className="text-xs font-bold uppercase text-gray-400">Result</span>
              {result ? (
                <img src={result} className="w-full h-64 object-cover rounded-2xl border-2 border-pink-500" alt="Edited" />
              ) : (
                <div className="w-full h-64 bg-gray-50 rounded-2xl flex items-center justify-center text-gray-400 italic">
                  Waiting for magic...
                </div>
              )}
            </div>
          </div>
        )}

        {source && (
          <div className="space-y-4">
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder='Try "Add a soft glow", "Change background to a spa setting", or "Apply a pink lip tint"'
              className="w-full p-4 bg-gray-50 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-pink-400 outline-none h-24 resize-none"
            />
            <div className="flex gap-4">
              <button
                onClick={handleEdit}
                disabled={loading || !prompt}
                className="flex-1 py-4 bg-pink-600 text-white rounded-2xl font-bold shadow-lg hover:bg-pink-700 disabled:opacity-50 flex items-center justify-center gap-2"
              >
                {loading ? <Loader2 className="animate-spin" /> : <><Wand2 size={20} /> Generate Magic</>}
              </button>
              <button 
                onClick={() => { setSource(null); setResult(null); setPrompt(''); }}
                className="p-4 bg-gray-100 text-gray-600 rounded-2xl hover:bg-gray-200"
              >
                <Trash2 size={24} />
              </button>
            </div>
          </div>
