import React, { useState, useRef, useEffect } from 'react';
import { CONSULTANTS } from '../constants';
import { startConsultantChat } from '../services/geminiService';
import { Send, User, ChevronLeft, Sparkles, Loader2 } from 'lucide-react';
import { GenerateContentResponse } from '@google/genai';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const AIConsultant: React.FC = () => {
  const [selectedChar, setSelectedChar] = useState<typeof CONSULTANTS[0] | null>(null);
  const [chat, setChat] = useState<any>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleCharSelect = (char: typeof CONSULTANTS[0]) => {
    setSelectedChar(char);
    const newChat = startConsultantChat(char.instruction);
    setChat(newChat);
    setMessages([{ role: 'model', text: `Hi! I'm ${char.name}. ${char.role === 'Cheerful Mascot' ? "I'm so excited to help you blend today! ✨" : `How can I assist you with your professional beauty goals today?`}` }]);
  };

  const handleSend = async () => {
    if (!input.trim() || !chat || isTyping) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const response = await chat.sendMessageStream({ message: userMessage });
      let fullText = '';

      // We add a temporary message to update as the stream comes in
      setMessages(prev => [...prev, { role: 'model', text: '' }]);

      for await (const chunk of response) {
        const c = chunk as GenerateContentResponse;
        fullText += c.text;
        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1] = { role: 'model', text: fullText };
          return updated;
        });
      }
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'model', text: "Sorry, I lost my connection for a moment. Could you try again?" }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (!selectedChar) {
    return (
      <div className="max-w-4xl mx-auto py-10 px-4">
        <div className="text-center mb-12">
