            <button
              key={char.id}
              onClick={() => handleCharSelect(char)}
              className="flex flex-col items-center group"
            >
              <div className="relative w-24 h-24 mb-4">
                <div className="absolute inset-0 bg-pink-100 rounded-full scale-0 group-hover:scale-110 transition-transform duration-300 -z-10" />
                <div className="w-full h-full rounded-full border-4 border-white shadow-lg overflow-hidden group-hover:border-pink-200 transition-colors">
                  <img src={char.iconUrl} alt={char.name} className="w-full h-full object-cover" />
                </div>
                <div className="absolute -bottom-1 -right-1 w-6 h-6 bg-green-500 border-2 border-white rounded-full flex items-center justify-center">
                  <div className="w-2 h-2 bg-white rounded-full animate-pulse" />
                </div>
              </div>
              <h4 className="font-bold text-gray-800 text-sm group-hover:text-pink-600 transition-colors">{char.name}</h4>
              <p className="text-[10px] uppercase font-bold text-gray-400 tracking-tighter">{char.role}</p>
            </button>
