import React, { useState, useEffect, useRef } from 'react';
import { Play, Pause, RotateCcw, Music, Volume2, VolumeX } from 'lucide-react';

interface RhythmTimerProps {
  onComplete?: () => void;
}

const RhythmTimer: React.FC<RhythmTimerProps> = ({ onComplete }) => {
  const [timeLeft, setTimeLeft] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [isActive, setIsActive] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const timerRef = useRef<number | null>(null);

  const startTimer = (seconds: number) => {
    setTotalTime(seconds);
    setTimeLeft(seconds);
    setIsActive(true);
  };

  const toggleActive = () => setIsActive(!isActive);

  const reset = () => {
    setIsActive(false);
    setTimeLeft(0);
    setTotalTime(0);
  };

  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      if (isActive && onComplete) onComplete();
      setIsActive(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft, onComplete]);

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const percentage = totalTime > 0 ? (timeLeft / totalTime) * 100 : 0;

  return (
    <div className="glass rounded-[40px] p-8 shadow-2xl border border-pink-100 flex flex-col items-center relative overflow-hidden">
      {/* Decorative background pulse when active */}
      {isActive && (
        <div className="absolute inset-0 bg-pink-400/5 animate-pulse -z-10" />
      )}

      <div className="text-center mb-6">
        <h3 className="font-bold text-gray-800 text-lg">Blending Rhythm Session</h3>
        <p className="text-xs text-pink-500 font-bold uppercase tracking-widest">Master the bounce</p>
      </div>

      <div className="relative w-56 h-56 mb-8 group">
        <svg className="w-full h-full -rotate-90">
          <circle
            cx="112"
            cy="112"
            r="100"
            fill="none"
            stroke="#fce7f3"
            strokeWidth="8"
          />
          <circle
            cx="112"
            cy="112"
            r="100"
            fill="none"
            stroke="url(#gradient)"
            strokeWidth="12"
            strokeDasharray={628.32}
            strokeDashoffset={628.32 - (628.32 * percentage) / 100}
            strokeLinecap="round"
            className="transition-all duration-1000 ease-linear"
          />
          <defs>
            <linearGradient id="gradient" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#ec4899" />
              <stop offset="100%" stopColor="#f43f5e" />
            </linearGradient>
          </defs>
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className="text-5xl font-bold text-gray-900 tracking-tighter">{formatTime(timeLeft)}</span>
          {isActive && (
            <div className="flex gap-1 mt-2">
              {[...Array(3)].map((_, i) => (
                <div key={i} className="w-1 h-3 bg-pink-400 rounded-full animate-bounce" style={{ animationDelay: `${i * 0.1}s` }} />
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="flex gap-3 mb-8">
        {[180, 300, 600].map((s) => (
          <button
            key={s}
            onClick={() => startTimer(s)}
            className={`px-5 py-2.5 rounded-2xl font-bold text-sm transition-all ${
              totalTime === s ? 'bg-pink-600 text-white shadow-lg' : 'bg-pink-50 text-pink-600 hover:bg-pink-100'
            }`}
          >
            {s / 60} MIN
          </button>
        ))}
      </div>

      <div className="flex items-center gap-6">
        <button
          onClick={() => setIsMuted(!isMuted)}
          className={`w-12 h-12 flex items-center justify-center rounded-full transition-colors ${isMuted ? 'text-gray-400' : 'text-pink-500 bg-pink-50'}`}
          title={isMuted ? "Unmute Lo-fi Blending Beats" : "Mute Lo-fi Blending Beats"}
        >
          {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} />}
        </button>

        <button
          onClick={toggleActive}
          disabled={timeLeft === 0}
          className={`w-20 h-20 flex items-center justify-center rounded-[30px] shadow-2xl transition-all active:scale-95 disabled:opacity-30 ${
            isActive ? 'bg-gray-900 text-white' : 'bg-pink-600 text-white hover:bg-pink-700'
          }`}
        >
          {isActive ? <Pause size={32} fill="currentColor" /> : <Play size={32} fill="currentColor" className="ml-1" />}
        </button>

        <button
          onClick={reset}
          className="w-12 h-12 flex items-center justify-center rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200 transition-colors"
        >
          <RotateCcw size={20} />
        </button>
      </div>

      <div className="mt-8 flex items-center gap-2 text-gray-400">
        <Music size={14} className={isActive && !isMuted ? 'animate-spin text-pink-400' : ''} />
        <span className="text-[10px] font-bold uppercase tracking-widest">
          {isActive && !isMuted ? 'Playing: Velvet Skin Lo-fi' : 'Rhythmic Audio Off'}
        </span>
      </div>
    </div>
  );
};

export default RhythmTimer;

import React, { useState, useRef, useEffect } from 'react';
import { CONSULTANTS, BRAND_ICONS } from '../constants';
import { startConsultantChat } from '../services/geminiService';
import { Send, User, ChevronLeft, Loader2, Zap } from 'lucide-react';
import { GenerateContentResponse } from '@google/genai';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const AIConsultant: React.FC = () => {
  const [selectedChar, setSelectedChar] = useState<typeof CONSULTANTS[0] | null>(null);
  const [chat, setChat] = useState<any>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleCharSelect = (char: typeof CONSULTANTS[0]) => {
    setSelectedChar(char);
    const newChat = startConsultantChat(char.instruction);
    setChat(newChat);
    setMessages([{ 
      role: 'model', 
      text: `Hi! I'm ${char.name}. ${char.role === 'Cheerful Mascot' ? "I'm so excited to help you blend today! ✨" : `How can I assist you with your professional beauty goals today?`}` 
    }]);
  };

  const handleSend = async () => {
    if (!input.trim() || !chat || isTyping) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const response = await chat.sendMessageStream({ message: userMessage });
      let fullText = '';

      setMessages(prev => [...prev, { role: 'model', text: '' }]);

      for await (const chunk of response) {
        const c = chunk as GenerateContentResponse;
        fullText += c.text;
        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1] = { role: 'model', text: fullText };
          return updated;
        });
      }
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'model', text: "Sorry, I lost my connection for a moment. Could you try again?" }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (!selectedChar) {
    return (
      <div className="max-w-6xl mx-auto py-16 px-6 animate-in fade-in slide-in-from-bottom-8 duration-700">
        <div className="text-center mb-20 max-w-2xl mx-auto">
          <h2 className="text-6xl font-bold mb-6 text-gray-900 tracking-tighter">Expert Concierge</h2>
          <p className="text-gray-500 text-xl font-light">Choose a specialized consultant to guide your technique. From clinical health to high-fashion artistry.</p>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-8">
          {CONSULTANTS.map((char) => (
            <button
              key={char.id}
              onClick={() => handleCharSelect(char)}
              className="flex flex-col items-center group perspective-1000"
            >
              <div className="relative w-32 h-32 mb-6 transition-transform duration-500 group-hover:scale-110 group-active:scale-95">
                <div className="absolute inset-0 bg-gradient-to-tr from-pink-500 to-rose-400 rounded-full scale-0 group-hover:scale-110 transition-transform duration-500 blur-xl opacity-20" />
                <div className="w-full h-full rounded-full border-4 border-white shadow-2xl overflow-hidden group-hover:border-pink-200 transition-all duration-500 bg-white relative z-10">
                  <img src={char.iconUrl} alt={char.name} className="w-full h-full object-cover" />
                </div>
                <div className="absolute bottom-1 right-1 w-8 h-8 bg-green-500 border-4 border-white rounded-full flex items-center justify-center z-20 shadow-md">
                  <div className="w-2.5 h-2.5 bg-white rounded-full animate-pulse" />
                </div>
              </div>
              <h4 className="font-bold text-gray-900 text-lg group-hover:text-pink-600 transition-colors leading-none mb-2">{char.name}</h4>
              <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest">{char.role}</p>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto h-[calc(100vh-14rem)] lg:h-[calc(100vh-10rem)] flex flex-col bg-white rounded-[50px] shadow-3xl overflow-hidden border border-pink-50 transition-all duration-500 animate-in zoom-in-95">
      {/* Header */}
      <div className="p-8 bg-pink-50/50 border-b border-pink-100 flex items-center gap-6 backdrop-blur-xl">
        <button 
          onClick={() => setSelectedChar(null)}
          className="p-3 hover:bg-white rounded-2xl transition-all text-pink-600 shadow-sm border border-pink-100/50"
        >
          <ChevronLeft size={24} />
        </button>
        <div className="w-16 h-16 rounded-[24px] overflow-hidden border-4 border-white shadow-lg">
          <img src={selectedChar.iconUrl} alt={selectedChar.name} className="w-full h-full object-cover" />
        </div>
        <div>
          <h3 className="font-bold text-2xl text-gray-900 leading-none mb-1 tracking-tight">{selectedChar.name}</h3>
          <p className="text-sm text-pink-500 font-bold uppercase tracking-widest">{selectedChar.role}</p>
        </div>
        <div className="ml-auto hidden sm:flex items-center gap-3 px-4 py-2 bg-white rounded-2xl shadow-sm border border-pink-100">
           <div className="w-2.5 h-2.5 bg-green-500 rounded-full animate-pulse" />
           <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Active Consultant</span>
        </div>
      </div>

      {/* Messages */}
      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-10 space-y-8 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] bg-fixed custom-scrollbar"
      >
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}>
            <div className={`max-w-[75%] flex items-end gap-5 ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
              <div className="w-10 h-10 rounded-2xl overflow-hidden shrink-0 border-2 border-white shadow-md bg-white">
                {m.role === 'user' ? (
                  <div className="w-full h-full bg-pink-600 flex items-center justify-center text-white">
                    <User size={20} />
                  </div>
                ) : (
                  <img src={selectedChar.iconUrl} alt={selectedChar.name} className="w-full h-full object-cover" />
                )}
              </div>
              <div className={`p-6 rounded-[30px] text-base leading-relaxed shadow-xl border ${
                m.role === 'user' 
                ? 'bg-gray-900 text-white rounded-br-none border-gray-800' 
                : 'bg-white text-gray-700 rounded-bl-none border-pink-50'
              }`}>
                {m.text || (i === messages.length - 1 && isTyping && <Loader2 className="animate-spin text-pink-400" size={20} />)}
              </div>
            </div>
          </div>
        ))}
        {isTyping && messages[messages.length-1]?.role === 'user' && (
          <div className="flex justify-start animate-in slide-in-from-bottom-2 duration-300">
            <div className="flex items-end gap-5">
              <div className="w-10 h-10 rounded-2xl overflow-hidden shrink-0 border-2 border-white shadow-md">
                <img src={selectedChar.iconUrl} alt={selectedChar.name} className="w-full h-full object-cover" />
              </div>
              <div className="p-6 bg-white border border-pink-50 rounded-[30px] rounded-bl-none shadow-xl flex items-center justify-center min-w-[80px]">
                <Loader2 className="animate-spin text-pink-300" size={24} />
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Input */}
      <div className="p-8 bg-white border-t border-pink-50/50 backdrop-blur-xl">
        <div className="relative flex items-center max-w-4xl mx-auto">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder={`Ask ${selectedChar.name} about blending...`}
            className="w-full p-6 pr-20 bg-gray-50 border-none rounded-[30px] focus:ring-4 focus:ring-pink-100 outline-none text-lg transition-all placeholder:text-gray-300 shadow-inner"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isTyping}
            className="absolute right-3 p-4 bg-pink-600 text-white rounded-[24px] hover:bg-pink-700 disabled:opacity-30 transition-all shadow-xl active:scale-95 flex items-center justify-center"
          >
            <Send size={24} />
          </button>
        </div>
      </div>
    </div>
  );
};

