import React, { useState, useEffect, useRef } from 'react';
import { BRAND_ICONS } from '../constants';

interface RhythmTimerProps {
  onComplete?: () => void;
}

const RhythmTimer: React.FC<RhythmTimerProps> = ({ onComplete }) => {
  const [timeLeft, setTimeLeft] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [isActive, setIsActive] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const timerRef = useRef<number | null>(null);

  const startTimer = (seconds: number) => {
    setTotalTime(seconds);
    setTimeLeft(seconds);
    setIsActive(true);
  };

  const toggleActive = () => setIsActive(!isActive);

  const reset = () => {
    setIsActive(false);
    setTimeLeft(0);
    setTotalTime(0);
  };

  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      if (isActive && onComplete) onComplete();
      setIsActive(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft, onComplete]);

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const percentage = totalTime > 0 ? (timeLeft / totalTime) * 100 : 0;

  return (
    <div className="glass rounded-[30px] md:rounded-[40px] p-6 md:p-8 shadow-xl md:shadow-2xl border border-pink-100 flex flex-col items-center relative overflow-hidden w-full max-w-md mx-auto">
      {isActive && (
        <div className="absolute inset-0 bg-pink-400/5 animate-pulse -z-10" />
      )}

      <div className="text-center mb-6">
        <h3 className="font-bold text-gray-800 text-sm md:text-lg tracking-tight">Blending Rhythm Session</h3>
        <p className="text-[10px] text-pink-500 font-bold uppercase tracking-widest mt-1">Master the bounce</p>
      </div>

      <div className="relative w-48 h-48 md:w-56 md:h-56 mb-6 md:mb-8 group">
        <svg className="w-full h-full -rotate-90">
          <circle
            cx="50%"
            cy="50%"
            r="42%"
            fill="none"
            stroke="#fce7f3"
            strokeWidth="8"
          />
          <circle
            cx="50%"
            cy="50%"
            r="42%"
            fill="none"
            stroke="url(#timerGradient)"
            strokeWidth="10"
            strokeDasharray="264%"
            strokeDashoffset={`${264 - (264 * percentage) / 100}%`}
            strokeLinecap="round"
            className="transition-all duration-1000 ease-linear"
          />
          <defs>
            <linearGradient id="timerGradient" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#ec4899" />
              <stop offset="100%" stopColor="#f43f5e" />
            </linearGradient>
          </defs>
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className="text-4xl md:text-5xl font-bold text-gray-900 tracking-tighter">{formatTime(timeLeft)}</span>
          {isActive && (
            <div className="flex gap-1 mt-2">
              {[...Array(3)].map((_, i) => (
                <div key={i} className="w-1 h-2.5 bg-pink-400 rounded-full animate-bounce" style={{ animationDelay: `${i * 0.1}s` }} />
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="flex gap-2 md:gap-3 mb-6 md:mb-8 w-full justify-center">
        {[180, 300, 600].map((s) => (
          <button
            key={s}
            onClick={() => startTimer(s)}
            className={`px-3 md:px-5 py-2 md:py-2.5 rounded-xl md:rounded-2xl font-bold text-[10px] md:text-sm transition-all flex-1 ${
              totalTime === s ? 'bg-pink-600 text-white shadow-lg' : 'bg-pink-50 text-pink-600 hover:bg-pink-100'
            }`}
          >
            {s / 60} MIN
          </button>
        ))}
      </div>

      <div className="flex items-center gap-4 md:gap-6">
        <button
          onClick={() => setIsMuted(!isMuted)}
          className={`w-10 h-10 md:w-12 md:h-12 flex items-center justify-center rounded-full transition-colors shrink-0 ${isMuted ? 'text-gray-400' : 'text-pink-500 bg-pink-50'}`}
        >
          {isMuted ? BRAND_ICONS.VolumeOff : BRAND_ICONS.VolumeOn}
        </button>

        <button
          onClick={toggleActive}
          disabled={timeLeft === 0}
          className={`w-16 h-16 md:w-20 md:h-20 flex items-center justify-center rounded-2xl md:rounded-[30px] shadow-xl transition-all active:scale-95 disabled:opacity-30 shrink-0 ${
            isActive ? 'bg-gray-900 text-white' : 'bg-pink-600 text-white hover:bg-pink-700'
          }`}
        >
          {isActive ? React.cloneElement(BRAND_ICONS.Pause as React.ReactElement, { size: 28 }) : React.cloneElement(BRAND_ICONS.Play as React.ReactElement, { size: 28, className: "ml-1" })}
        </button>

        <button
          onClick={reset}
          className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center rounded-full bg-gray-100 text-gray-500 hover:bg-gray-200 transition-colors shrink-0"
        >
          {React.cloneElement(BRAND_ICONS.Rotate as React.ReactElement, { size: 20 })}
        </button>
      </div>

      <div className="mt-6 md:mt-8 flex items-center gap-2 text-gray-400">
        <span className={isActive && !isMuted ? 'animate-spin text-pink-400 shrink-0' : 'shrink-0'}>{BRAND_ICONS.Music}</span>
        <span className="text-[8px] md:text-[10px] font-bold uppercase tracking-widest truncate">
          {isActive && !isMuted ? 'Playing: Velvet Skin Lo-fi' : 'Rhythmic Audio Off'}
        </span>
      </div>
    </div>
  );
};

export default RhythmTimer;

import React, { useState } from 'react';
import { SkinType, FinishType, QuizState, SpongeRecommendation } from '../types';
import { APP_ASSETS, BRAND_ICONS } from '../constants';

const Quiz: React.FC = () => {
  const [step, setStep] = useState(0);
  const [quiz, setQuiz] = useState<QuizState>({
    skinType: null,
    finish: null,
    formula: null,
    concern: null,
  });
  const [result, setResult] = useState<SpongeRecommendation | null>(null);

  const steps = [
    {
      title: "What's your skin type?",
      key: 'skinType',
      options: Object.values(SkinType),
    },
    {
      title: "Desired finish?",
      key: 'finish',
      options: Object.values(FinishType),
    },
    {
      title: "Favorite formula?",
      key: 'formula',
      options: ['Liquid', 'Cream', 'Stick', 'Cushion'],
    },
    {
      title: "Main concern?",
      key: 'concern',
      options: ['Coverage', 'Longevity', 'Blendability'],
    }
  ];

  const handleSelect = (val: any) => {
    const updated = { ...quiz, [steps[step].key]: val };
    setQuiz(updated);
    if (step < steps.length - 1) {
      setStep(step + 1);
    } else {
      generateResult(updated);
    }
  };

  const generateResult = (data: QuizState) => {
    const rec: SpongeRecommendation = {
      shape: data.finish === FinishType.MATTE ? 'Angled Flat Edge' : 'Classic Teardrop',
      material: data.skinType === SkinType.DRY ? 'Hydrophilic Velvet' : 'Latex-Free PU',
      reason: `Based on your ${data.skinType} skin and preference for a ${data.finish} finish, this ${data.formula}-optimized sponge will solve your ${data.concern} issues.`,
      imageUrl: APP_ASSETS.quizResultImage
    };
    setResult(rec);
  };

  if (result) {
    return (
      <div className="bg-white rounded-[30px] md:rounded-[50px] p-6 md:p-12 shadow-xl animate-in zoom-in duration-500 text-center max-w-2xl mx-auto border border-pink-50 w-full overflow-hidden">
        <div className="inline-block p-3 md:p-4 bg-pink-100 text-pink-600 rounded-xl md:rounded-[20px] mb-6 md:mb-8 shadow-sm">
          {React.cloneElement(BRAND_ICONS.Star as React.ReactElement, { size: 24, className: "fill-current" })}
        </div>
        <h2 className="text-2xl md:text-4xl font-bold text-gray-900 mb-1 tracking-tight">Your Perfect Match!</h2>
        <p className="text-pink-500 font-bold uppercase tracking-widest text-[10px] mb-8">The "Precision Pro" Artist Series</p>

        <div className="relative w-56 h-56 md:w-72 md:h-72 mx-auto mb-8 md:mb-12 group shrink-0">
          <div className="absolute inset-0 bg-gradient-to-tr from-pink-200 to-rose-100 rounded-full blur-2xl opacity-30" />
          <img src={result.imageUrl} alt="Recommended Sponge" className="relative z-10 w-full h-full object-cover rounded-[30px] md:rounded-[40px] shadow-lg transform rotate-2 group-hover:rotate-0 transition-transform duration-700" />
        </div>

        <div className="space-y-4 md:space-y-6 text-left bg-pink-50/50 p-6 md:p-8 rounded-[25px] md:rounded-[35px] mb-8 md:mb-10 border border-pink-100/50">
          <div>
            <h4 className="font-bold text-pink-600 uppercase text-[8px] tracking-[0.15em] mb-0.5">Optimal Shape</h4>
            <p className="text-gray-900 font-semibold text-base md:text-lg truncate">{result.shape}</p>
          </div>
          <div>
            <h4 className="font-bold text-pink-600 uppercase text-[8px] tracking-[0.15em] mb-0.5">Ideal Material</h4>
            <p className="text-gray-900 font-semibold text-base md:text-lg truncate">{result.material}</p>
          </div>
          <p className="text-xs md:text-base text-gray-600 leading-relaxed font-light italic border-l-4 border-pink-400 pl-4 md:pl-6">
            "{result.reason}"
          </p>
        </div>

        <button 
          onClick={() => { setStep(0); setResult(null); }}
          className="flex items-center justify-center gap-2 w-full py-4 md:py-6 bg-pink-600 text-white rounded-xl md:rounded-[25px] font-bold shadow-lg hover:bg-pink-700 transition-all active:scale-95 text-sm md:text-base"
        >
          {React.cloneElement(BRAND_ICONS.Reset as React.ReactElement, { size: 18 })} Retake Quiz
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-xl mx-auto py-4 md:py-12 w-full px-2">
      <div className="flex justify-between items-center mb-8">
        <h2 className="text-xl md:text-3xl font-bold tracking-tight text-gray-900 shrink-0">Step {step + 1}</h2>
        <div className="flex-1 max-w-[150px] md:max-w-[200px] h-2 bg-gray-100 rounded-full overflow-hidden border border-gray-50 ml-4">
          <div 
            className="h-full bg-pink-600 rounded-full transition-all duration-700" 
            style={{ width: `${((step + 1) / steps.length) * 100}%` }}
          />
        </div>
      </div>

      <div className="bg-white rounded-[30px] md:rounded-[40px] p-6 md:p-10 shadow-xl border border-pink-50">
        <h3 className="text-lg md:text-2xl font-bold text-gray-900 mb-6 md:mb-8 tracking-tight">{steps[step].title}</h3>
        <div className="space-y-3 md:space-y-4">
          {steps[step].options.map((opt) => (
            <button
              key={opt}
              onClick={() => handleSelect(opt)}
              className="group w-full flex justify-between items-center p-4 md:p-6 rounded-xl md:rounded-[25px] border-2 border-gray-50 hover:border-pink-300 hover:bg-pink-50 transition-all text-left"
            >
              <span className="font-semibold text-gray-700 group-hover:text-pink-600 text-sm md:text-base">{opt}</span>
              <div className="text-pink-200 group-hover:text-pink-400 shrink-0">
                {BRAND_ICONS.Next}
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Quiz;

import React, { useState } from 'react';
import { analyzeMakeupResult } from '../services/geminiService';
import { DiagnosticReport } from '../types';
import { BRAND_ICONS } from '../constants';

const AIDiagnosis: React.FC = () => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [report, setReport] = useState<DiagnosticReport | null>(null);

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!image) return;
    setLoading(true);
    try {
      const base64 = image.split(',')[1];
      const result = await analyzeMakeupResult(base64);
      setReport(result);
    } catch (err) {
      alert("Failed to analyze. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6 md:space-y-8 px-2">
      <div className="bg-white rounded-[30px] p-6 md:p-8 shadow-xl text-center border border-pink-50">
        <h2 className="text-2xl md:text-3xl font-bold mb-2 tracking-tight">Today's Look AI</h2>
        <p className="text-gray-500 text-xs md:text-base mb-6 md:mb-8">Upload a selfie for pro blend feedback.</p>

        {!image ? (
          <label className="flex flex-col items-center justify-center w-full h-48 md:h-64 border-2 border-dashed border-pink-200 rounded-[20px] md:rounded-3xl cursor-pointer hover:bg-pink-50 transition-colors">
            <span className="text-pink-400 mb-3">{React.cloneElement(BRAND_ICONS.Upload as React.ReactElement, { size: 40 })}</span>
            <span className="text-gray-600 text-xs md:text-sm font-medium">Click to upload photo</span>
            <input type="file" className="hidden" accept="image/*" onChange={handleUpload} />
          </label>
        ) : (
          <div className="space-y-4 md:space-y-6">
            <div className="relative h-64 md:h-80 w-full overflow-hidden rounded-2xl shadow-md border-2 border-pink-50">
              <img src={image} alt="Selfie" className="w-full h-full object-cover" />
            </div>
            {!report && (
              <button
                onClick={handleAnalyze}
                disabled={loading}
                className="w-full py-4 bg-pink-600 text-white rounded-xl font-bold shadow-lg hover:bg-pink-700 disabled:opacity-50 flex items-center justify-center gap-2 text-sm md:text-base"
              >
                {loading ? React.cloneElement(BRAND_ICONS.Loading as React.ReactElement, { className: "animate-spin" }) : "Analyze My Look"}
              </button>
            )}
            <button 
              onClick={() => { setImage(null); setReport(null); }}
              className="text-pink-600 text-xs md:text-sm font-semibold hover:underline"
            >
              Upload Different Photo
            </button>
          </div>
        )}
      </div>

      {report && (
        <div className="bg-white rounded-[30px] p-6 md:p-8 shadow-xl animate-in slide-in-from-bottom-4 duration-500 border border-pink-50">
          <div className="flex items-center justify-between mb-6 md:mb-8">
            <div className="min-w-0">
              <h3 className="text-xl md:text-2xl font-bold truncate">Diagnostic Report</h3>
              <p className="text-gray-500 text-[10px] md:text-xs">Based on AI analysis</p>
            </div>
            <div className="text-right shrink-0">
              <span className="text-3xl md:text-5xl font-bold text-pink-600">{report.overallScore}</span>
              <span className="text-pink-300 font-bold text-xs md:text-lg">/100</span>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3 md:gap-4 mb-6 md:mb-8">
            {Object.entries(report.dimensions).map(([key, val]) => (
              <div key={key} className="p-3 md:p-4 bg-pink-50/50 rounded-xl md:rounded-2xl border border-pink-100">
                <div className="flex justify-between items-center mb-1.5 md:mb-2">
                  <span className="text-[8px] md:text-[10px] uppercase font-bold text-pink-600 tracking-wider truncate mr-1">
                    {key.replace(/([A-Z])/g, ' $1')}
                  </span>
                  <span className="shrink-0">
                    {(val as number) >= 80 ? React.cloneElement(BRAND_ICONS.Check as React.ReactElement, { size: 14, className: "text-green-500" }) : React.cloneElement(BRAND_ICONS.Alert as React.ReactElement, { size: 14, className: "text-amber-500" })}
                  </span>
                </div>
                <div className="w-full h-1 md:h-1.5 bg-pink-100 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-pink-500 rounded-full transition-all duration-1000" 
                    style={{ width: `${val}%` }}
                  />
                </div>
              </div>
            ))}
          </div>

          <div className="bg-gray-50 p-4 md:p-6 rounded-2xl border-l-4 border-pink-500 shadow-sm">
            <h4 className="font-bold text-gray-800 text-sm md:text-base mb-1 md:mb-2">Expert Advice</h4>
            <p className="text-xs md:text-sm text-gray-600 leading-relaxed font-light">{report.advice}</p>
          </div>
        </div>
      )}
    </div>
  );
};

