import React, { useState, useRef, useEffect } from 'react';
import { CONSULTANTS, BRAND_ICONS } from '../constants';
import { startConsultantChat } from '../services/geminiService';
import { GenerateContentResponse } from '@google/genai';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const AIConsultant: React.FC = () => {
  const [selectedChar, setSelectedChar] = useState<typeof CONSULTANTS[0] | null>(null);
  const [chat, setChat] = useState<any>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleCharSelect = (char: typeof CONSULTANTS[0]) => {
    setSelectedChar(char);
    const newChat = startConsultantChat(char.instruction);
    setChat(newChat);
    setMessages([{ 
      role: 'model', 
      text: `Hi! I'm ${char.name}. ${char.role === 'Cheerful Mascot' ? "I'm so excited to help you blend today! ✨" : `How can I assist you with your professional beauty goals today?`}` 
    }]);
  };

  const handleSend = async () => {
    if (!input.trim() || !chat || isTyping) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const response = await chat.sendMessageStream({ message: userMessage });
      let fullText = '';

      setMessages(prev => [...prev, { role: 'model', text: '' }]);

      for await (const chunk of response) {
        const c = chunk as GenerateContentResponse;
        fullText += c.text;
        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1] = { role: 'model', text: fullText };
          return updated;
        });
      }
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'model', text: "Sorry, I lost my connection for a moment. Could you try again?" }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (!selectedChar) {
    return (
      <div className="max-w-6xl mx-auto py-8 md:py-16 px-4 md:px-6 animate-in fade-in slide-in-from-bottom-8 duration-700">
        <div className="text-center mb-10 md:mb-20 max-w-2xl mx-auto">
          <h2 className="text-4xl md:text-6xl font-bold mb-4 md:mb-6 text-gray-900 tracking-tighter">Artistry Concierge</h2>
          <p className="text-gray-500 text-base md:text-xl font-light">Choose a specialized consultant to guide your technique. Swap these photos anytime in constants.tsx.</p>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-4 md:gap-8">
          {CONSULTANTS.map((char) => (
            <button
              key={char.id}
              onClick={() => handleCharSelect(char)}
              className="flex flex-col items-center group active:scale-95 transition-transform"
            >
              <div className="relative w-20 h-20 md:w-32 md:h-32 mb-4 md:mb-6 shrink-0 transition-all duration-500">
                <div className="absolute inset-0 bg-pink-500 rounded-full blur-xl opacity-0 group-hover:opacity-20 transition-opacity" />
                <div className="w-full h-full rounded-full border-2 md:border-4 border-white shadow-lg overflow-hidden group-hover:border-pink-200 transition-all duration-500 bg-white relative z-10">
                  <img src={char.iconUrl} alt={char.name} className="w-full h-full object-cover" />
                </div>
                <div className="absolute bottom-0 right-0 w-6 h-6 md:w-8 md:h-8 bg-green-500 border-2 md:border-4 border-white rounded-full flex items-center justify-center z-20 shadow-md">
                  <div className="w-2 h-2 md:w-2.5 md:h-2.5 bg-white rounded-full animate-pulse" />
                </div>
              </div>
              <h4 className="font-bold text-gray-900 text-sm md:text-lg group-hover:text-pink-600 transition-colors leading-none mb-1 md:mb-2 text-center">{char.name}</h4>
              <p className="text-[8px] md:text-[10px] uppercase font-bold text-gray-400 tracking-widest text-center">{char.role}</p>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto h-[calc(100vh-10rem)] md:h-[calc(100vh-12rem)] flex flex-col bg-white rounded-[30px] md:rounded-[50px] shadow-2xl overflow-hidden border border-pink-50 transition-all duration-500 animate-in zoom-in-95">
      {/* Header */}
      <div className="p-4 md:p-8 bg-pink-50/50 border-b border-pink-100 flex items-center gap-4 md:gap-6 backdrop-blur-xl">
        <button 
          onClick={() => setSelectedChar(null)}
          className="p-2 md:p-3 hover:bg-white rounded-xl md:rounded-2xl transition-all text-pink-600 shadow-sm shrink-0"
        >
          {React.cloneElement(BRAND_ICONS.Back as React.ReactElement, { size: 20 })}
        </button>
        <div className="w-10 h-10 md:w-16 md:h-16 rounded-xl md:rounded-[24px] overflow-hidden border-2 md:border-4 border-white shadow-md shrink-0 bg-white">
          <img src={selectedChar.iconUrl} alt={selectedChar.name} className="w-full h-full object-cover" />
        </div>
        <div className="min-w-0">
          <h3 className="font-bold text-lg md:text-2xl text-gray-900 leading-none mb-0.5 md:mb-1 tracking-tight truncate">{selectedChar.name}</h3>
          <p className="text-[10px] md:text-sm text-pink-500 font-bold uppercase tracking-widest truncate">{selectedChar.role}</p>
        </div>
        <div className="ml-auto hidden sm:flex items-center gap-2 px-3 py-1.5 bg-white rounded-xl shadow-sm border border-pink-100 shrink-0">
           <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
           <span className="text-[8px] font-bold text-gray-500 uppercase tracking-widest">Connected</span>
        </div>
      </div>

      {/* Messages */}
      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 md:p-10 space-y-4 md:space-y-8 bg-gray-50/30 custom-scrollbar"
      >
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}>
            <div className={`max-w-[85%] md:max-w-[75%] flex items-end gap-3 md:gap-5 ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
              <div className="w-8 h-8 md:w-10 md:h-10 rounded-lg md:rounded-2xl overflow-hidden shrink-0 border border-white shadow-sm bg-white">
                {m.role === 'user' ? (
                  <div className="w-full h-full bg-pink-600 flex items-center justify-center text-white">
                    {React.cloneElement(BRAND_ICONS.User as React.ReactElement, { size: 16 })}
                  </div>
                ) : (
                  <img src={selectedChar.iconUrl} alt={selectedChar.name} className="w-full h-full object-cover" />
                )}
              </div>
              <div className={`p-4 md:p-6 rounded-2xl md:rounded-[30px] text-sm md:text-base leading-relaxed shadow-md border ${
                m.role === 'user' 
                ? 'bg-gray-900 text-white rounded-br-none border-gray-800' 
                : 'bg-white text-gray-700 rounded-bl-none border-pink-50'
              }`}>
                {m.text || (i === messages.length - 1 && isTyping && React.cloneElement(BRAND_ICONS.Loading as React.ReactElement, { size: 16, className: "animate-spin text-pink-400" }))}
              </div>
            </div>
          </div>
        ))}
        {isTyping && messages[messages.length-1]?.role === 'user' && (
          <div className="flex justify-start animate-in slide-in-from-bottom-2 duration-300">
            <div className="flex items-end gap-3 md:gap-5">
              <div className="w-8 h-8 md:w-10 md:h-10 rounded-lg md:rounded-2xl overflow-hidden shrink-0 border border-white shadow-sm bg-white">
                <img src={selectedChar.iconUrl} alt={selectedChar.name} className="w-full h-full object-cover" />
              </div>
              <div className="p-4 md:p-6 bg-white border border-pink-50 rounded-2xl md:rounded-[30px] rounded-bl-none shadow-md flex items-center justify-center min-w-[60px]">
                {React.cloneElement(BRAND_ICONS.Loading as React.ReactElement, { size: 20, className: "animate-spin text-pink-300" })}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Input */}
      <div className="p-4 md:p-8 bg-white border-t border-pink-50/50">
        <div className="relative flex items-center max-w-4xl mx-auto w-full">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder={`Ask ${selectedChar.name}...`}
            className="w-full p-4 md:p-6 pr-14 md:pr-20 bg-gray-50 border-none rounded-2xl md:rounded-[30px] focus:ring-4 focus:ring-pink-100 outline-none text-sm md:text-lg transition-all placeholder:text-gray-400 shadow-inner"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isTyping}
            className="absolute right-2 md:right-3 p-3 md:p-4 bg-pink-600 text-white rounded-xl md:rounded-[24px] hover:bg-pink-700 disabled:opacity-30 transition-all shadow-lg active:scale-95 flex items-center justify-center shrink-0"
          >
            {React.cloneElement(BRAND_ICONS.Send as React.ReactElement, { size: 20 })}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AIConsultant;

import React, { useState, useRef, useEffect } from 'react';
import { CONSULTANTS, BRAND_ICONS, APP_ASSETS } from '../constants';
import { startConsultantChat } from '../services/geminiService';
import { GenerateContentResponse } from '@google/genai';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const AIConsultant: React.FC = () => {
  const [selectedChar, setSelectedChar] = useState<typeof CONSULTANTS[0] | null>(null);
  const [chat, setChat] = useState<any>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleCharSelect = (char: typeof CONSULTANTS[0]) => {
    setSelectedChar(char);
    const newChat = startConsultantChat(char.instruction);
    setChat(newChat);
    setMessages([{ 
      role: 'model', 
      text: `Hi! I'm ${char.name}. ${char.role === 'Cheerful Mascot' ? "I'm so excited to help you blend today! ✨" : `How can I assist you with your professional beauty goals today?`}` 
    }]);
  };

  const handleSend = async () => {
    if (!input.trim() || !chat || isTyping) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const response = await chat.sendMessageStream({ message: userMessage });
      let fullText = '';

      setMessages(prev => [...prev, { role: 'model', text: '' }]);

      for await (const chunk of response) {
        const c = chunk as GenerateContentResponse;
        fullText += c.text;
        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1] = { role: 'model', text: fullText };
          return updated;
        });
      }
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'model', text: "Sorry, I lost my connection for a moment. Could you try again?" }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (!selectedChar) {
    return (
      <div className="max-w-6xl mx-auto py-8 md:py-16 px-4 md:px-6 animate-in fade-in slide-in-from-bottom-8 duration-700">
        <div className="text-center mb-10 md:mb-20 max-w-2xl mx-auto">
          <h2 className="text-4xl md:text-6xl font-bold mb-4 md:mb-6 text-gray-900 tracking-tighter">Artistry Concierge</h2>
          <p className="text-gray-500 text-base md:text-xl font-light">Choose a specialized consultant to guide your technique. Swap these photos anytime in constants.tsx.</p>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-4 md:gap-8">
          {CONSULTANTS.map((char) => (
            <button
              key={char.id}
              onClick={() => handleCharSelect(char)}
              className="flex flex-col items-center group active:scale-95 transition-transform"
            >
              <div className="relative w-20 h-20 md:w-32 md:h-32 mb-4 md:mb-6 shrink-0 transition-all duration-500">
                <div className="absolute inset-0 bg-pink-500 rounded-full blur-xl opacity-0 group-hover:opacity-20 transition-opacity" />
                <div className="w-full h-full rounded-full border-2 md:border-4 border-white shadow-lg overflow-hidden group-hover:border-pink-200 transition-all duration-500 bg-white relative z-10">
                  <img src={char.iconUrl} alt={char.name} className="w-full h-full object-cover" />
                </div>
                <div className="absolute bottom-0 right-0 w-6 h-6 md:w-8 md:h-8 bg-green-500 border-2 md:border-4 border-white rounded-full flex items-center justify-center z-20 shadow-md">
                  <div className="w-2 h-2 md:w-2.5 md:h-2.5 bg-white rounded-full animate-pulse" />
                </div>
              </div>
              <h4 className="font-bold text-gray-900 text-sm md:text-lg group-hover:text-pink-600 transition-colors leading-none mb-1 md:mb-2 text-center">{char.name}</h4>
              <p className="text-[8px] md:text-[10px] uppercase font-bold text-gray-400 tracking-widest text-center">{char.role}</p>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto h-[calc(100vh-10rem)] md:h-[calc(100vh-12rem)] flex flex-col bg-white rounded-[30px] md:rounded-[50px] shadow-2xl overflow-hidden border border-pink-50 transition-all duration-500 animate-in zoom-in-95">
      {/* Header */}
      <div className="p-4 md:p-8 bg-pink-50/50 border-b border-pink-100 flex items-center gap-4 md:gap-6 backdrop-blur-xl">
        <button 
          onClick={() => setSelectedChar(null)}
          className="p-2 md:p-3 hover:bg-white rounded-xl md:rounded-2xl transition-all text-pink-600 shadow-sm shrink-0"
        >
          {React.cloneElement(BRAND_ICONS.Back as React.ReactElement, { size: 20 })}
        </button>
        <div className="w-10 h-10 md:w-16 md:h-16 rounded-xl md:rounded-[24px] overflow-hidden border-2 md:border-4 border-white shadow-md shrink-0 bg-white">
          <img src={selectedChar.iconUrl} alt={selectedChar.name} className="w-full h-full object-cover" />
        </div>
        <div className="min-w-0">
          <h3 className="font-bold text-lg md:text-2xl text-gray-900 leading-none mb-0.5 md:mb-1 tracking-tight truncate">{selectedChar.name}</h3>
          <p className="text-[10px] md:text-sm text-pink-500 font-bold uppercase tracking-widest truncate">{selectedChar.role}</p>
        </div>
        <div className="ml-auto hidden sm:flex items-center gap-2 px-3 py-1.5 bg-white rounded-xl shadow-sm border border-pink-100 shrink-0">
           <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
           <span className="text-[8px] font-bold text-gray-500 uppercase tracking-widest">Connected</span>
        </div>
      </div>

      {/* Messages */}
      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 md:p-10 space-y-4 md:space-y-8 bg-gray-50/30 custom-scrollbar"
      >
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}>
            <div className={`max-w-[85%] md:max-w-[75%] flex items-end gap-3 md:gap-5 ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
              <div className="w-8 h-8 md:w-10 md:h-10 rounded-lg md:rounded-2xl overflow-hidden shrink-0 border border-white shadow-sm bg-white">
                {m.role === 'user' ? (
                  <img src={APP_ASSETS.userAvatarUrl} alt="You" className="w-full h-full object-cover" />
                ) : (
                  <img src={selectedChar.iconUrl} alt={selectedChar.name} className="w-full h-full object-cover" />
                )}
              </div>
              <div className={`p-4 md:p-6 rounded-2xl md:rounded-[30px] text-sm md:text-base leading-relaxed shadow-md border ${
                m.role === 'user' 
                ? 'bg-gray-900 text-white rounded-br-none border-gray-800' 
                : 'bg-white text-gray-700 rounded-bl-none border-pink-50'
              }`}>
                {m.text || (i === messages.length - 1 && isTyping && React.cloneElement(BRAND_ICONS.Loading as React.ReactElement, { size: 16, className: "animate-spin text-pink-400" }))}
              </div>
            </div>
          </div>
        ))}
        {isTyping && messages[messages.length-1]?.role === 'user' && (
          <div className="flex justify-start animate-in slide-in-from-bottom-2 duration-300">
            <div className="flex items-end gap-3 md:gap-5">
              <div className="w-8 h-8 md:w-10 md:h-10 rounded-lg md:rounded-2xl overflow-hidden shrink-0 border border-white shadow-sm bg-white">
                <img src={selectedChar.iconUrl} alt={selectedChar.name} className="w-full h-full object-cover" />
              </div>
              <div className="p-4 md:p-6 bg-white border border-pink-50 rounded-2xl md:rounded-[30px] rounded-bl-none shadow-md flex items-center justify-center min-w-[60px]">
                {React.cloneElement(BRAND_ICONS.Loading as React.ReactElement, { size: 20, className: "animate-spin text-pink-300" })}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Input */}
      <div className="p-4 md:p-8 bg-white border-t border-pink-50/50">
        <div className="relative flex items-center max-w-4xl mx-auto w-full">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder={`Ask ${selectedChar.name}...`}
            className="w-full p-4 md:p-6 pr-14 md:pr-20 bg-gray-50 border-none rounded-2xl md:rounded-[30px] focus:ring-4 focus:ring-pink-100 outline-none text-sm md:text-lg transition-all placeholder:text-gray-400 shadow-inner"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isTyping}
            className="absolute right-2 md:right-3 p-3 md:p-4 bg-pink-600 text-white rounded-xl md:rounded-[24px] hover:bg-pink-700 disabled:opacity-30 transition-all shadow-lg active:scale-95 flex items-center justify-center shrink-0"
          >
            {React.cloneElement(BRAND_ICONS.Send as React.ReactElement, { size: 20 })}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AIConsultant;
